/*
 * Vendored typefaces (assets/fonts, SIL OFL), loaded with the FontFace API:
 *  - desktop / userscript: base64 woff2 embedded in the payload, loaded from an
 *    ArrayBuffer: no network request, unaffected by the page's CSP;
 *  - extension: the woff2 files are web accessible resources of the extension.
 * __BD_FONTS__ is generated by scripts/build.mjs. A family is registered only when
 * it is used (the chosen pair, a theme's fonts, the previews in the settings).
 * If anything fails, the fallback stacks (Segoe UI Variable, system-ui) take over.
 *
 * The user picks a pair in Settings > Appearance (setting "font"). The default pair
 * leaves the theme's own fonts alone; any other pair wins over them.
 */
BD.fonts = {
  DEFAULT: "grotesk",
  pairs: [
    { id: "grotesk", display: "Space Grotesk", ui: "Inter" },
    { id: "classic", display: "Bricolage Grotesque", ui: "Instrument Sans" },
    { id: "manrope", display: "Manrope", ui: "Manrope" },
    { id: "sora", display: "Sora", ui: "DM Sans" },
    { id: "outfit", display: "Outfit", ui: "Figtree" },
    { id: "jakarta", display: "Plus Jakarta Sans", ui: "Plus Jakarta Sans" }
  ],
  loaded: new Set(),

  pair(id = BD.settings.get("font", this.DEFAULT)) {
    return this.pairs.find((p) => p.id === id) || this.pairs[0];
  },

  stack(family, role) {
    return `"${family}", ${role === "display" ? '"Segoe UI Variable Display"' : '"Segoe UI Variable Text"'}, system-ui, sans-serif`;
  },

  /** Register every file of a vendored family once. Unknown names are ignored. */
  ensure(family) {
    if (this.loaded.has(family) || typeof __BD_FONTS__ === "undefined" || !document.fonts || typeof FontFace !== "function") return;
    this.loaded.add(family);
    const runtime = globalThis.chrome?.runtime || globalThis.browser?.runtime;
    for (const f of __BD_FONTS__.filter((x) => x.family === family)) {
      try {
        let source;
        if (f.data) source = this.decode(f.data);
        else if (runtime?.getURL) source = `url("${runtime.getURL(`fonts/${f.file}`)}") format("woff2")`;
        else continue;
        const face = new FontFace(f.family, source, { weight: f.weight, unicodeRange: f.range, display: "swap" });
        document.fonts.add(face);
        face.load().catch((err) => BD.warn(`font ${f.file} failed:`, err));
      } catch (err) {
        BD.warn(`font ${f.file} failed:`, err);
      }
    }
  },

  decode(b64) {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  },

  /** Vendored families named in a CSS font stack ("Space Grotesk", Georgia, serif). */
  familiesIn(stack) {
    const names = new Set((typeof __BD_FONTS__ !== "undefined" ? __BD_FONTS__ : []).map((f) => f.family));
    return String(stack || "")
      .split(",")
      .map((s) => s.trim().replace(/^["']|["']$/g, ""))
      .filter((s) => names.has(s));
  },

  /** Load what the page needs now: the chosen pair, or the default pair plus the theme's fonts. */
  apply() {
    const pair = this.pair();
    const root = document.documentElement.style;
    this.ensure(pair.display);
    this.ensure(pair.ui);
    if (pair.id === this.DEFAULT) {
      root.removeProperty("--bd-font-display");
      root.removeProperty("--bd-font-ui");
      const css = getComputedStyle(document.documentElement);
      for (const v of ["--bd-font-display", "--bd-font-ui"]) this.familiesIn(css.getPropertyValue(v)).forEach((f) => this.ensure(f));
    } else {
      root.setProperty("--bd-font-display", this.stack(pair.display, "display"));
      root.setProperty("--bd-font-ui", this.stack(pair.ui, "ui"));
    }
  },

  /** Switch pair with a cross-fade (View Transitions, or a short fade), none if motion is reduced. */
  async set(id) {
    const pair = this.pair(id);
    this.ensure(pair.display);
    this.ensure(pair.ui);
    // Wait for the new faces so the fade does not land on a fallback font.
    await Promise.race([
      Promise.all([document.fonts.load(`700 1em "${pair.display}"`), document.fonts.load(`400 1em "${pair.ui}"`)]).catch(() => {}),
      new Promise((r) => setTimeout(r, 600))
    ]);
    const swap = () => {
      BD.settings.set("font", pair.id);
      this.apply();
    };
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) return swap();
    if (typeof document.startViewTransition === "function") {
      document.documentElement.dataset.bdFontSwitch = "";
      const t = document.startViewTransition(swap);
      t.finished.finally(() => delete document.documentElement.dataset.bdFontSwitch);
      return t.updateCallbackDone;
    }
    const body = document.body;
    if (typeof body.animate !== "function") return swap();
    await body.animate([{ opacity: 1 }, { opacity: 0.25 }], { duration: 140, easing: "ease-in", fill: "forwards" }).finished.catch(() => {});
    swap();
    body.animate([{ opacity: 0.25 }, { opacity: 1 }], { duration: 220, easing: "ease-out" });
    body.getAnimations().filter((a) => a.effect?.getComputedTiming().fill === "forwards").forEach((a) => a.cancel());
  }
};

BD.feature({
  id: "fonts",
  setup() {
    BD.fonts.apply();
    BD.on("skin", () => BD.fonts.apply());
  }
});
